1	/**
2	 * Renders a react-email component to the `{ subject, html, text }` triple
3	 * `EmailService` sends.
4	 *
5	 * `EmailTemplate` is the closed vocabulary of templates; this module is the
6	 * only place that maps a name to a component and to a subject line, so
7	 * adding a template means touching exactly one switch in each direction.
8	 */
9	import { render } from "@react-email/components";
10	import { createElement, type ReactElement } from "react";
11	import { SITE_CONFIG } from "@/config/site";
12	import type {
13	  EmailTemplate,
14	  RenderedEmail,
15	} from "@/server/services/email-service";
16	import { DigestEmail, type DigestEmailProps } from "./digest-email";
17	import { InviteEmail, type InviteEmailProps } from "./invite-email";
18	import { InvoiceEmail, type InvoiceEmailProps } from "./invoice-email";
19	import { MentionEmail, type MentionEmailProps } from "./mention-email";
20	import { OverdueEmail, type OverdueEmailProps } from "./overdue-email";
21	import {
22	  PasswordResetEmail,
23	  type PasswordResetEmailProps,
24	} from "./password-reset-email";
25	import { WelcomeEmail, type WelcomeEmailProps } from "./welcome-email";
26	
27	type Props = Readonly<Record<string, unknown>>;
28	
29	/** Reads a string prop defensively — templates are fed loosely typed payloads. */
